// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 amount, address receiver) public {
        // Bound amount to avoid overflow issues
        amount = bound(amount, 1, 1e30);
        // Ensure receiver is not zero address (contract requires it)
        vm.assume(receiver != address(0));
        // Ensure caller is not the keeper (to test revert)
        vm.assume(caller != address(this) && caller != address(0));

        // Prank as caller to attempt pauseDeposit
        vm.prank(caller);

        // Try to call pauseDeposit and capture revert status
        bool reverted;
        try c.pauseDeposit() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Assert that the call reverted (only keeper can pause)
        assertTrue(reverted, "Non-keeper should not be able to pause deposits");
    }
}

